window.__PAGES=window.__PAGES||{};window.__PAGES["pages/statistic.html"]="<!-- Statistic / Laporan Page -->\n<style>\n.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px}\n.stat-big{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:20px;text-align:center}\n.stat-big .val{font-size:32px;font-weight:700}.stat-big .lbl{font-size:12px;color:var(--muted);margin-top:4px}\n.chart-row{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px}\n.chart-box{background:var(--card);border:1px solid var(--border);border-radius:var(--radius);padding:18px}\n.chart-box h4{font-size:14px;margin-bottom:12px}\n.bar-chart{display:flex;align-items:flex-end;gap:6px;height:180px;padding-top:10px}\n.bar-col{display:flex;flex-direction:column;align-items:center;gap:4px;flex:1}\n.bar{background:var(--accent);border-radius:4px 4px 0 0;min-width:28px;transition:.3s;width:100%}\n.bar-label{font-size:10px;color:var(--muted)}\n.bar-val{font-size:11px;font-weight:600}\n.agent-table{width:100%;border-collapse:collapse;font-size:13px}\n.agent-table th{text-align:left;padding:8px 10px;font-size:11px;color:var(--muted);border-bottom:2px solid var(--border);text-transform:uppercase}\n.agent-table td{padding:8px 10px;border-bottom:1px solid var(--border)}\n</style>\n\n<div class=\"page-header\"><h1>📊 Laporan</h1></div>\n<div class=\"page-body\">\n  <div class=\"stats-grid\">\n    <div class=\"stat-big\"><div class=\"val\" id=\"st-total\"></div><div class=\"lbl\">Total Percakapan</div></div>\n    <div class=\"stat-big\"><div class=\"val\" id=\"st-week\"></div><div class=\"lbl\">Minggu Ini</div></div>\n    <div class=\"stat-big\"><div class=\"val\" id=\"st-avg\"></div><div class=\"lbl\">Rata-rata Respons</div></div>\n    <div class=\"stat-big\"><div class=\"val\" id=\"st-rate\"></div><div class=\"lbl\">Resolution Rate</div></div>\n  </div>\n  <div class=\"chart-row\">\n    <div class=\"chart-box\">\n      <h4>Percakapan per Hari (7 hari terakhir)</h4>\n      <div class=\"bar-chart\" id=\"weeklyChart\"></div>\n    </div>\n    <div class=\"chart-box\">\n      <h4>Channel Distribution</h4>\n      <div class=\"bar-chart\" id=\"channelChart\"></div>\n    </div>\n  </div>\n  <div class=\"chart-box\" style=\"margin-bottom:16px\">\n    <h4>Performa Agen</h4>\n    <table class=\"agent-table\">\n      <thead><tr><th>Agen</th><th>Handled</th><th>Avg Response</th><th>CSAT</th></tr></thead>\n      <tbody id=\"agentPerf\"></tbody>\n    </table>\n  </div>\n</div>\n\n<script>\nconst s=DB.statistics;\ndocument.getElementById('st-total').textContent=s.conversations.total.toLocaleString('id-ID');\ndocument.getElementById('st-week').textContent=s.conversations.thisWeek;\ndocument.getElementById('st-avg').textContent=s.conversations.avgResponseTime;\ndocument.getElementById('st-rate').textContent=s.conversations.resolutionRate;\n\n// Weekly bar chart\nconst days=['Sen','Sel','Rab','Kam','Jum','Sab','Min'];\nconst maxW=Math.max(...s.weekly);\ndocument.getElementById('weeklyChart').innerHTML=s.weekly.map((v,i)=>`<div class=\"bar-col\"><div class=\"bar-val\">${v}</div><div class=\"bar\" style=\"height:${(v/maxW)*150}px\"></div><div class=\"bar-label\">${days[i]}</div></div>`).join('');\n\n// Channel chart\nconst ch=s.channels;\nconst maxC=Math.max(ch.whatsappApi,ch.whatsappWeb);\ndocument.getElementById('channelChart').innerHTML=`\n  <div class=\"bar-col\"><div class=\"bar-val\">${ch.whatsappApi}</div><div class=\"bar\" style=\"height:${(ch.whatsappApi/maxC)*150}px;background:#25d366\"></div><div class=\"bar-label\">WA API</div></div>\n  <div class=\"bar-col\"><div class=\"bar-val\">${ch.whatsappWeb}</div><div class=\"bar\" style=\"height:${(ch.whatsappWeb/maxC)*150}px;background:#128c7e\"></div><div class=\"bar-label\">WA Web</div></div>`;\n\n// Agent performance\ndocument.getElementById('agentPerf').innerHTML=s.agents.map(a=>`<tr>\n  <td><b>${a.name}</b></td><td>${a.handled}</td><td>${a.avgResponse}</td><td>⭐ ${a.csat}</td>\n</tr>`).join('');\n</script>\n";
